# src/index.js —— Dva 项目入口

import dva from 'dva'

// 1. 创建 app 实例
const app = dva()

// 2. 注册 Model（可注册多个）
app.model({
  namespace: 'counter',
  state: { count: 0 },
  reducers: {
    add(state) {
      return { ...state, count: state.count + 1 }
    }
  }
})

// 3. 注册路由
app.router(({ history }) => {
  return <div>Hello Dva</div>
})

// 4. 挂载到 #root
app.start('#root')


# 💡 dva() 会内部创建 Redux Store + Saga Middleware
# 💡 app.model() 自动生成 reducer/saga/action type
# 💡 省掉了手写 constants/actions/reducers 的繁琐

# models/counter.js —— 完整 model 示例

export default {
  namespace: 'counter',

  state: {
    count: 0
  },

  # ===== Reducers（同步修改 state） =====
  reducers: {
    // state 是当前状态，{ payload } 是传入数据
    add(state, { payload = 1 }) {
      return { ...state, count: state.count + payload }
    },

    minus(state) {
      return { ...state, count: state.count - 1 }
    },

    reset() {
      return { count: 0 }  // 直接返回新state
    },

    // 和 Pinia $patch 类似的批量更新
    setCount(state, { payload }) {
      return { ...state, count: payload }
    }
  }
}


# 💡 reducers 的 key 变成 action type：
#    'counter/add'      ← namespace/reducerName
#    'counter/minus'
# 💡 payload 是 dispatch 传入的第二个参数
# 💡 必须返回新 state（不可变更新）

# models/todo.js —— effects 完整示例

import * as api from '@/services/todo'  // API 层

export default {
  namespace: 'todo',

  state: {
    list: [],
    loading: false
  },

  reducers: {
    setList(state, { payload }) {
      return { ...state, list: payload }
    },
    setLoading(state, { payload }) {
      return { ...state, loading: payload }
    },
    addItem(state, { payload }) {
      return { ...state, list: [...state.list, payload] }
    },
    removeItem(state, { payload: id }) {
      return { ...state, list: state.list.filter(i => i.id !== id) }
    }
  },

  # ===== Effects（Generator 函数） =====
  effects: {
    // yield call: 调用异步函数
    // yield put:  dispatch action（触发 reducer）
    *fetchList({ payload }, { call, put, select }) {
      yield put({ type: 'setLoading', payload: true })

      try {
        const data = yield call(api.getTodos)
        yield put({ type: 'setList', payload: data })
      } finally {
        yield put({ type: 'setLoading', payload: false })
      }
    },

    *addTodo({ payload: text }, { call, put, select }) {
      // 先调 API，后改本地 state
      const newItem = yield call(api.addTodo, text)
      yield put({ type: 'addItem', payload: newItem })
    },

    *removeTodo({ payload: id }, { call, put }) {
      yield call(api.deleteTodo, id)
      yield put({ type: 'removeItem', payload: id })
    }
  },

