import { connect } from 'dva'

function Counter({ count, dispatch }) {
  return (
    <div>
      <h2>Count: {count}</h2>
      <button onClick={() =>
        dispatch({
          type: 'counter/add',
          payload: 1
        })
      }>+1</button>
      <button onClick={() =>
        dispatch({ type: 'counter/minus' })
      }>-1</button>
      <button onClick={() =>
        dispatch({ type: 'counter/reset' })
      }>Reset</button>
    </div>
  )
}

// connect：把 model state 注入到 props
// ({ counter }) 的 counter 来自 namespace
const mapStateToProps = ({ counter }) => ({
  count: counter.count
})

export default connect(mapStateToProps)(Counter)


# 💡 connect 的返回值是「增强后的组件」
# 💡 dispatch type 格式: 'namespace/reducerName'
# 💡 可以 connect 多个 model：({ a, b }) => ({ ...a, ...b })

# Subscriptions —— 路由初始化 / 数据预加载

export default {
  namespace: 'user',

  state: { profile: null },

  reducers: {
    setProfile(state, { payload }) {
      return { ...state, profile: payload }
    }
  },

  effects: {
    *fetchProfile({ payload }, { call, put }) {
      const data = yield call(api.getUser)
      yield put({ type: 'setProfile', payload: data })
    }
  },

  # ===== Subscriptions =====
  subscriptions: {
    // 方式1：app 启动时执行
    setup({ dispatch, history }) {
      // 监听路由变化
      history.listen(({ pathname }) => {
        if (pathname === '/user') {
          dispatch({ type: 'fetchProfile' })
        }
      })
    },

    // 方式2：直接 dispatch（app 启动时）
    init({ dispatch }) {
      dispatch({ type: 'fetchProfile' })
    }
  }
}


# 💡 subscriptions 在 app.start() 后自动执行
# 💡 最适合「进页面时自动拉数据」的场景
# 💡 比在组件 useEffect 里 dispatch 更解耦

# ===== src/models/todo.js =====

export default {
  namespace: 'todo',

  state: {
    list: [],
    nextId: 1
  },

  reducers: {
    // 从 localStorage 恢复
    restore(state, { payload }) {
      return { ...state, list: payload }
    },
    // 添加
    add(state, { payload: text }) {
      const id = state.nextId
      return {
        ...state,
        nextId: id + 1,
        list: [...state.list, { id, text, done: false }]
      }
    },
    // 切换完成状态
    toggle(state, { payload: id }) {
      return {
        ...state,
        list: state.list.map(item =>
          item.id === id
            ? { ...item, done: !item.done }
            : item
        )
      }
    },
    // 删除
    remove(state, { payload: id }) {
      return {
        ...state,
        list: state.list.filter(item => item.id !== id)
      }
    }
  },

  effects: {
    // 模拟异步保存
    *sync({ payload }, { call, select }) {
      const { todo } = yield select()
      localStorage.setItem(
        'dva-todos',
        JSON.stringify(todo.list)
      )
    }
  },

  subscriptions: {
    setup({ dispatch }) {
      // 从 localStorage 恢复数据
      const saved = localStorage.getItem('dva-todos')
      if (saved) {
        dispatch({
          type: 'restore',
          payload: JSON.parse(saved)
        })
      }
    }
  }
}


# ===== 组件中使用 =====
import { connect } from 'dva'

function TodoApp({ list, dispatch }) {
  return (
    <div>
      <input onKeyUp={(e) => { if (e.key==='Enter') {
        dispatch({ type: 'todo/add', payload: e.target.value })
        dispatch({ type: 'todo/sync' })
        e.target.value = ''
      }}} />
      {list.map(item => (
        <div key={item.id}
          onClick={() => {
            dispatch({ type: 'todo/toggle', payload: item.id })
            dispatch({ type: 'todo/sync' })
          }}>
          {item.done ? '✅' : '⬜'} {item.text}
        </div>
      ))}
    </div>
  )
}

export default connect(
  ({ todo }) => ({ list: todo.list })
)(TodoApp)


